/* ============================================================================
 * config.h — hand-rolled Android/NDK configuration for building
 * libgphoto2 / libgphoto2_port / libusb-1.0 / camlibs/ptp2 with CMake.
 *
 * This replaces the config.h normally generated by ./configure (or meson).
 * ========================================================== */
#ifndef ANDROID_GP_CONFIG_H
#define ANDROID_GP_CONFIG_H

#define VERSION                          "2.5.31"
#define PACKAGE                          "libgphoto2"
#define PACKAGE_NAME                     "gPhoto2 (Android NDK port)"
#define PACKAGE_VERSION                  VERSION

#define GETTEXT_PACKAGE_LIBGPHOTO2       "libgphoto2"
#define GETTEXT_PACKAGE_LIBGPHOTO2_PORT  "libgphoto2_port"
#define GP_CAMLIB_SET                    "ptp2"   /* version banner: camlibs we ship */
#define LOCALEDIR                        "/system/locale"  /* unused: NLS off  */
#define GP_CONFIG_FILE                   "/dev/null"       /* no config writes */

/* --- NLS / iconv: disabled, i18n.h falls back to plain strings ------------- */
#undef ENABLE_NLS
#undef HAVE_ICONV
#undef HAVE_LIBXML2
#undef HAVE_LIBJPEG
#undef HAVE_LIBEXIF

/* --- libc / POSIX features available in bionic ---------------------------- */
#define HAVE_LSTAT
#define HAVE_REGEX
#define HAVE_SETENV 1
#define HAVE_INET_ATON
#define HAVE_SYS_TIME_H
#define HAVE_SYS_PARAM_H
#define HAVE_UNISTD_H
#define HAVE_STDLIB_H
#define HAVE_STRING_H
#define HAVE_STRINGS_H
#define HAVE_STDINT_H
#define HAVE_INTTYPES_H
#define HAVE_VASPRINTF
#define HAVE_VA_COPY
#define HAVE_ASPRINTF
#define HAVE_GMTIME_R
#define HAVE_LOCALTIME_R
#define HAVE_MEMMEM
#define HAVE_SELECT

/* --- libgphoto2_port ------------------------------------------------------ */
#define HAVE_LTDL   /* provided by our dlopen()-based libltdl shim */
#define IOLIB_LIST  "usb1"     /* version banner; the iolibs we ship */
/* Fallback dirs; at runtime camera_bridge.cpp overrides both via setenv(). */
#define IOLIBS  "/system/lib"
#define CAMLIBS "/system/lib"

/* --------------------------------------------------------------------------
 * USB: THE ANDROID FILE-DESCRIPTOR WORKAROUND
 *
 * 1) HAVE_LIBUSB_WRAP_SYS_DEVICE enables gp_port_usb_set_sys_device(int fd) /
 *    gp_port_usb_get_sys_device() in gphoto2-port.c and makes the libusb1
 *    iolib call libusb_wrap_sys_device() instead of raw USB enumeration.
 *
 * 2) HAVE_LIBUSB_OPTION_NO_DEVICE_DISCOVERY makes the iolib execute
 *    libusb_set_option(NULL, LIBUSB_OPTION_NO_DEVICE_DISCOVERY, NULL),
 *    which is mandatory on stock Android where UsbManager owns discovery.
 *    Requires libusb >= 1.0.23 (1.0.27 recommended).
 *
 * camera_bridge.cpp calls gp_port_usb_set_sys_device(fd) *before*
 * gp_port_info_list_load() / gp_camera_init().
 * -------------------------------------------------------------------------- */
#define HAVE_LIBUSB_WRAP_SYS_DEVICE   1
#define HAVE_LIBUSB_OPTION_NO_DEVICE_DISCOVERY 1

/* --- camlibs/ptp2 ---------------------------------------------------------- */
#define HAVE_LIBUSB1 1

#endif /* ANDROID_GP_CONFIG_H */
